insert into public.posts (id, type, slug, title, dek, topic_id, author_id, status, featured, published_at, reading_minutes, hero, body, footnotes, corrections, video, claim, dispatch, related_slug) values ('9bb9e4dc-4bed-da9f-1d2c-713da08ed89c', 'article', 'tel-dan-stele-house-of-david', 'What the Tel Dan Stele does — and doesn’t — tell us about the House of David', 'A careful reading of one of the most cited inscriptions in biblical archaeology, separating what the stone says from what has been claimed about it.', (select id from public.topics where slug = 'archaeology'), (select id from public.authors where slug = 'editor'), 'published', true, '2026-10-04T13:00:00Z', 14, '{"src":null,"alt":"Fragments of the Tel Dan Stele","caption":"The Tel Dan Stele fragments, now in the Israel Museum, Jerusalem.","credit":"[Photo credit]"}'::jsonb, '[{"type":"p","text":"In the summer of 1993, a team excavating at Tel Dan in northern Israel noticed a piece of inscribed basalt reused in a later wall. Within a year, two smaller fragments had turned up nearby. Together they preserve part of a ninth-century BC Aramaic victory inscription, and one short phrase on it has been argued over ever since: *bytdwd*, “House of David.”[^1]"},{"type":"p","text":"Before 1993, some scholars doubted that David was anything more than a literary figure. The stele changed the shape of that conversation. But it is worth slowing down to ask what the stone actually says, and what it can and cannot carry."},{"type":"h2","text":"What the inscription says"},{"type":"p","text":"The text is written in the voice of an Aramean king, most often identified as Hazael of Damascus. He boasts of killing a king of Israel and a king of the “House of David.” The names are damaged, but the most common restoration reads them as Joram son of Ahab and Ahaziah son of Joram, the same pair who appear together at war with Hazael in 2 Kings 8:28.[^2]"},{"type":"quote","text":"[I killed Jo]ram son of [Ahab], king of Israel, and [I] killed [Ahaz]iah son of [Joram, kin]g of the House of David.","cite":"Tel Dan Stele (restored; brackets mark damaged text)"},{"type":"p","text":"The phrase “House of David” works the way “House of Omri” does in Assyrian records: a dynasty named for its founder. That is the significance. A foreign enemy, writing perhaps 150 years after David’s reign, names the Judean royal line after him — the very promise of a lasting house that 2 Samuel 7:16 puts at the center of David’s story."},{"type":"h2","text":"Where the Bible and the stele differ"},{"type":"p","text":"The stele and Scripture do not tell the story the same way. In 2 Kings 9:24, it is Jehu, not Hazael, who kills Joram, and Jehu’s men also kill Ahaziah. Scholars have offered several explanations: Hazael may be claiming credit for a coup he encouraged, Jehu may have acted as his ally, or the stele may simply be royal propaganda, which ancient victory inscriptions very often are.[^3]"},{"type":"callout","title":"Our read","text":"The difference is real and worth stating plainly. It does not undermine the stele’s main value, which is the dynastic name, but it is a good reminder that ancient kings wrote to impress, not to footnote."},{"type":"h2","text":"The objections, fairly stated"},{"type":"p","text":"A minority of scholars questioned the reading early on. Some noted that *bytdwd* lacks the word divider the scribe uses elsewhere, and suggested it named a place or a temple rather than a dynasty. Others raised questions about how the fragments were found. These objections have been examined at length, and the dynastic reading is now the clear majority view, though not a unanimous one.[^4]"},{"type":"p","text":"A related claim is that the Mesha Stele, from Moab, also mentions the House of David. That reading, proposed by André Lemaire in 1994, depends on damaged letters and remains genuinely debated.[^5]"},{"type":"h2","text":"What it doesn’t prove"},{"type":"p","text":"The stele is strong evidence that a dynasty traced itself to a founder named David and was known by that name to its neighbors within a few generations. It does not, on its own, confirm the size of David’s kingdom or the details of any particular story about him. Holding those two things apart is exactly what careful readers should do — the Bereans of Acts 17:11 were commended for examining things to see whether they were so."}]'::jsonb, '[{"n":1,"text":"Biran and Naveh, “An Aramaic Stele Fragment from Tel Dan,” 81–98.","source_id":"1754f0f0-c87f-8d25-93b8-f245b52423c1"},{"n":2,"text":"Biran and Naveh, “The Tel Dan Inscription: A New Fragment,” 1–18.","source_id":"5de38908-ffb5-5cae-9c2c-4d707f09e43b"},{"n":3,"text":"Kitchen, On the Reliability of the Old Testament.","source_id":"fc2f163a-3115-1d40-d499-a1609e4f96c8"},{"n":4,"text":"Hagelia, The Dan Debate, surveys the full range of readings.","source_id":"54c29793-d4b0-e718-0b54-4e2eb5d4ad23"},{"n":5,"text":"Lemaire, “House of David Restored in Moabite Inscription.”","source_id":"3e3247e3-7bc1-1b3e-adf7-a4361e98909b"}]'::jsonb, '[{"date":"2026-10-05","text":"An earlier version gave the discovery year of the two smaller fragments as 1993. They were found in 1994."}]'::jsonb, null, null, null, null) on conflict (id) do nothing;
