insert into public.post_sources (post_id, source_id, sort) values ('9bb9e4dc-4bed-da9f-1d2c-713da08ed89c', '3e3247e3-7bc1-1b3e-adf7-a4361e98909b', 4) on conflict do nothing;
insert into public.posts (id, type, slug, title, dek, topic_id, author_id, status, featured, published_at, reading_minutes, hero, body, footnotes, corrections, video, claim, dispatch, related_slug) values ('640c2f0f-44f7-d057-cfe5-aed7457ea1a2', 'article', 'why-historians-date-the-corinthian-creed-early', 'Why historians date the creed in 1 Corinthians 15 so early', 'Paul quotes a summary of the faith he says he “received.” Scholars across the spectrum agree it is very old. Here is why, and what that does and doesn’t establish.', (select id from public.topics where slug = 'apologetics'), (select id from public.authors where slug = 'editor'), 'published', false, '2026-10-01T13:00:00Z', 11, '{"src":null,"alt":"An early papyrus page of Paul’s letters","caption":"A page from an early papyrus codex of Paul’s letters.","credit":"[Photo credit]"}'::jsonb, '[{"type":"p","text":"Paul wrote 1 Corinthians in the mid-50s AD. In chapter 15, he pauses to remind the church of something he had passed on to them, something he says he had himself received. What follows in 1 Corinthians 15:3–8 reads less like Paul’s own prose and more like a compact, memorized summary.[^1]"},{"type":"h2","text":"The marks of an older tradition"},{"type":"p","text":"Several features point to a formula Paul is quoting rather than composing. “Received” and “delivered” were standard terms for handing on tradition. The lines are balanced and repetitive (“and that… and that…”), the names are Aramaic forms like *Cephas*, and the vocabulary is unusual for Paul.[^2]"},{"type":"p","text":"Paul also tells us when he had the opportunity to receive it. In Galatians 1:18, he describes visiting Jerusalem three years after his conversion and staying fifteen days with Peter. Many scholars think that visit, or one close to it, is where Paul learned this summary."},{"type":"callout","title":"Across the spectrum","text":"This is not only an apologist’s argument. Critical scholars such as Gerd Lüdemann and Bart Ehrman also date the tradition behind the creed very early, within a few years of the crucifixion."},{"type":"h2","text":"What early dating does establish"},{"type":"p","text":"If the creed was formulated within a few years of Jesus’ death, then the belief that he had died, been buried and appeared alive to named individuals and groups was not a late legend. It was there at the start, and Paul even notes that most of the five hundred witnesses were still living, an open invitation to check.[^3]"},{"type":"h2","text":"What it doesn’t establish on its own"},{"type":"p","text":"Early belief is not the same as a proven event. Historians who accept the early date still disagree about what the first followers experienced. Ehrman, for example, accepts that followers sincerely believed they saw Jesus but does not conclude he rose.[^4] The creed sets the starting point for that debate; it does not end it."}]'::jsonb, '[{"n":1,"text":"Dunn, Jesus Remembered, on the resurrection traditions.","source_id":"b4bb4330-2e0e-f2a5-2c74-4c7995615286"},{"n":2,"text":"Habermas and Licona, The Case for the Resurrection of Jesus.","source_id":"44d237c4-ef1d-92b1-8260-01fde3c279ed"},{"n":3,"text":"Lüdemann, The Resurrection of Jesus.","source_id":"4ca70b15-bd27-1e10-5012-c50ee143ca30"},{"n":4,"text":"Ehrman, How Jesus Became God.","source_id":"92cdc36e-fe82-1469-276a-6e7181e50fec"}]'::jsonb, '[]'::jsonb, null, null, null, null) on conflict (id) do nothing;
