insert into public.posts (id, type, slug, title, dek, topic_id, author_id, status, featured, published_at, reading_minutes, hero, body, footnotes, corrections, video, claim, dispatch, related_slug) values ('9b3ee728-2110-2a62-ca8b-06101b4e7f81', 'article', 'what-the-council-of-nicaea-actually-decided', 'What the Council of Nicaea actually decided — and what it didn’t', 'In AD 325 the bishops met to settle a dispute about Christ. They did not choose the books of the Bible.', (select id from public.topics where slug = 'church-history'), (select id from public.authors where slug = 'editor'), 'published', false, '2026-09-27T13:00:00Z', 9, '{"src":null,"alt":"An icon depicting the First Council of Nicaea","caption":"A later icon depicting the First Council of Nicaea.","credit":"[Image credit]"}'::jsonb, '[{"type":"p","text":"The emperor Constantine summoned bishops from across the empire to Nicaea in AD 325. The pressing issue was the teaching of Arius, a presbyter in Alexandria, who held that the Son was a created being and that “there was when he was not.”[^1]"},{"type":"h2","text":"The decision"},{"type":"p","text":"The council rejected Arius’ view and issued a creed confessing the Son to be *homoousios*, “of the same substance,” with the Father. The bishops pointed to texts such as John 1:1–3, where the Word is with God, is God, and is the one through whom all things were made."},{"type":"p","text":"The council also addressed practical matters: how to calculate the date of Easter, a schism in Egypt, and twenty canons on church order.[^2]"},{"type":"h2","text":"What it didn’t do"},{"type":"p","text":"None of the surviving records of the council — its creed, its canons, or the accounts by people who were there — discuss which books belong in the Bible. The idea that Nicaea “chose the canon” is a much later story. The New Testament canon took shape gradually, through use in the churches, well before and after 325.[^3]"}]'::jsonb, '[{"n":1,"text":"Socrates Scholasticus, Ecclesiastical History, Book I.","source_id":"7babf10f-7e91-8c5f-480f-eb402ba4bbcf"},{"n":2,"text":"Ayres, Nicaea and Its Legacy.","source_id":"254a3945-c8f4-3028-4135-67f7330bf836"},{"n":3,"text":"Metzger, The Canon of the New Testament.","source_id":"84992b6d-3a40-8cc6-ae27-e9ada981bc7b"}]'::jsonb, '[]'::jsonb, null, null, null, null) on conflict (id) do nothing;
