insert into public.posts (id, type, slug, title, dek, topic_id, author_id, status, featured, published_at, reading_minutes, hero, body, footnotes, corrections, video, claim, dispatch, related_slug) values ('23287437-b159-dad7-1085-2cd2fe256c1c', 'article', 'the-great-isaiah-scroll-and-the-hebrew-text', 'The Great Isaiah Scroll and a thousand years of copying', 'Found in 1947, the scroll let scholars compare Isaiah across a millennium of hand copying. What did they find?', (select id from public.topics where slug = 'bible-manuscripts'), (select id from public.authors where slug = 'editor'), 'published', false, '2026-09-22T13:00:00Z', 8, '{"src":null,"alt":"A column of the Great Isaiah Scroll","caption":"A column of the Great Isaiah Scroll (1QIsaᵃ).","credit":"[Image credit]"}'::jsonb, '[{"type":"p","text":"Before the Dead Sea Scrolls, the oldest complete Hebrew manuscripts of Isaiah came from the medieval period. The Great Isaiah Scroll, found in Qumran Cave 1 in 1947, is usually dated to the second century BC — roughly a thousand years earlier.[^1]"},{"type":"h2","text":"What the comparison showed"},{"type":"p","text":"The scroll is strikingly close to the later Masoretic text. Most differences are in spelling and grammar. There are meaningful variants too, and some have been adopted by modern translations, but none changes the book’s substance.[^2]"},{"type":"p","text":"For readers, it is a vivid illustration of Isaiah 40:8 — and an equally vivid reminder that textual criticism is careful work, not a slogan."}]'::jsonb, '[{"n":1,"text":"Abegg, Flint and Ulrich, The Dead Sea Scrolls Bible.","source_id":"81275ab4-df64-6bdd-a201-c1877b91e048"},{"n":2,"text":"Tov, Textual Criticism of the Hebrew Bible, 3rd ed.","source_id":"d7a4d905-b1a7-db6c-42f8-a00959ecbef3"}]'::jsonb, '[]'::jsonb, null, null, null, null) on conflict (id) do nothing;
