insert into public.posts (id, type, slug, title, dek, topic_id, author_id, status, featured, published_at, reading_minutes, hero, body, footnotes, corrections, video, claim, dispatch, related_slug) values ('e302cd9d-6e90-149a-0f40-32d1c89d88ac', 'dispatch', 'excavation-season-wraps-northern-tell', '[Sample] Excavation season wraps at a northern Israel tell', 'A short news brief: what was found, who found it, and why it matters.', (select id from public.topics where slug = 'archaeology'), (select id from public.authors where slug = 'editor'), 'published', false, '2026-10-05T19:00:00Z', null, null, '[{"type":"p","text":"Sample dispatch. Dispatches are short briefs: two or three paragraphs summarizing a new find, publication or claim, with a link to the original report and a line on why it matters to readers."},{"type":"p","text":"Scripture references still work here, so a brief on a dig at Dan can point readers to 1 Kings 12:29."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, null, '{"label":"Excavation news","original_outlet":"[Original outlet]","original_url":null}'::jsonb, null) on conflict (id) do nothing;
insert into public.posts (id, type, slug, title, dek, topic_id, author_id, status, featured, published_at, reading_minutes, hero, body, footnotes, corrections, video, claim, dispatch, related_slug) values ('c5db24b7-96d8-ced1-35e2-4bc96678bb9c', 'dispatch', 'papyrus-fragment-newly-published', '[Sample] A New Testament papyrus fragment is newly published', 'A short news brief on a manuscript publication.', (select id from public.topics where slug = 'bible-manuscripts'), (select id from public.authors where slug = 'editor'), 'published', false, '2026-10-04T15:00:00Z', null, null, '[{"type":"p","text":"Sample dispatch. Replace with a summary of the publication, its date range, and what scholars are saying about it."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, null, '{"label":"Manuscripts","original_outlet":"[Original outlet]","original_url":null}'::jsonb, null) on conflict (id) do nothing;
