insert into public.posts (id, type, slug, title, dek, topic_id, author_id, status, featured, published_at, reading_minutes, hero, body, footnotes, corrections, video, claim, dispatch, related_slug) values ('241a8003-05e9-9453-8ad3-6c537d135d25', 'video', 'walking-tel-dan', 'Walking Tel Dan: the gate, the high place and the stele', 'An on-site tour of the city where the “House of David” inscription was found.', (select id from public.topics where slug = 'archaeology'), (select id from public.authors where slug = 'editor'), 'published', false, '2026-10-03T12:00:00Z', null, null, '[{"type":"p","text":"We walk the site from the springs to the gate complex, stop at the platform associated with Jeroboam’s shrine (1 Kings 12:29), and stand where the stele fragments were recovered."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"youtube_id":null,"duration":"24:10","series":"On Site","chapters":[{"t":"0:00","label":"Arriving at Tel Dan"},{"t":"3:40","label":"The Middle Bronze Age gate"},{"t":"9:15","label":"The cult platform of Jeroboam"},{"t":"15:30","label":"Where the stele was found"},{"t":"21:05","label":"What it means"}],"transcript":[{"type":"p","text":"[Transcript placeholder. Paste or import the episode transcript here.]"}]}'::jsonb, null, null, null) on conflict (id) do nothing;
