insert into public.posts (id, type, slug, title, dek, topic_id, author_id, status, featured, published_at, reading_minutes, hero, body, footnotes, corrections, video, claim, dispatch, related_slug) values ('547b4293-898a-18e3-c885-de1735354b0c', 'video', 'did-nicaea-choose-the-bible', 'Did the Council of Nicaea choose the Bible?', 'Testing a claim that won’t go away against what the council’s own records say.', (select id from public.topics where slug = 'church-history'), (select id from public.authors where slug = 'editor'), 'published', false, '2026-09-29T12:00:00Z', null, null, '[{"type":"p","text":"Companion video to our Claims Examined review. The full written review, with sources, is linked below."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, '{"youtube_id":null,"duration":"18:45","series":"Claims Examined","chapters":[{"t":"0:00","label":"The claim"},{"t":"4:20","label":"What the records say"},{"t":"11:00","label":"How the canon formed"}],"transcript":[{"type":"p","text":"[Transcript placeholder.]"}]}'::jsonb, null, null, null) on conflict (id) do nothing;
