insert into public.posts (id, type, slug, title, dek, topic_id, author_id, status, featured, published_at, reading_minutes, hero, body, footnotes, corrections, video, claim, dispatch, related_slug) values ('3febb818-dbf1-fbab-92a7-4dd107929995', 'claim', 'tel-dan-stele-house-of-david', 'The Tel Dan Stele refers to the “House of David.”', 'Does a ninth-century BC inscription really name David’s dynasty?', (select id from public.topics where slug = 'archaeology'), (select id from public.authors where slug = 'editor'), 'published', false, '2026-10-02T12:00:00Z', null, null, '[{"type":"p","text":"See our long read on the stele for the full discussion, including where the inscription and 2 Kings 9:24 tell the story differently."}]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '{"statement":"The Tel Dan Stele refers to the “House of David.”","origin":"Widely cited in apologetics and in popular coverage of biblical archaeology since 1993.","rating":"well_supported","confidence":"high","summary":"The phrase bytdwd is clearly legible on the main fragment, and the dynastic reading “House of David” is the strong majority view among epigraphers. Alternative readings exist but have not gained wide acceptance.","evidence_for":["The letters are clear on the main fragment, published by the excavators in 1993.","“House of X” is a standard way to name a dynasty in the period, as with “House of Omri.”","The context pairs it with the “king of Israel,” fitting the two kingdoms of 2 Kings 8:28."],"evidence_against":["There is no word divider between “house” and “David,” which some read as a place name.","A minority questioned the excavation context of the fragments."],"reviewed_at":"2026-10-02","history":[{"date":"2026-10-02","text":"First published."}]}'::jsonb, null, 'tel-dan-stele-house-of-david') on conflict (id) do nothing;
