insert into public.posts (id, type, slug, title, dek, topic_id, author_id, status, featured, published_at, reading_minutes, hero, body, footnotes, corrections, video, claim, dispatch, related_slug) values ('d5b10c0c-9187-25f3-991d-b0dd64434d53', 'claim', 'exodus-dated-to-1446-bc', 'The Exodus can be firmly dated to 1446 BC.', 'An early date and a late date both have serious defenders.', (select id from public.topics where slug = 'archaeology'), (select id from public.authors where slug = 'editor'), 'published', false, '2026-09-30T12:00:00Z', null, null, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '{"statement":"The Exodus can be firmly dated to 1446 BC.","origin":"Derived from the 480 years of 1 Kings 6:1, counted back from Solomon’s fourth year.","rating":"debated","confidence":"moderate","summary":"Scholars who accept a historical Exodus divide mainly between an early date (mid-15th century BC) and a late date (13th century BC). Each reads the biblical numbers and the archaeological evidence differently. “Firmly” overstates the case.","evidence_for":["1 Kings 6:1 gives 480 years from the Exodus to the temple’s founding, pointing to about 1446 BC.","Defenders argue destruction evidence at some Canaanite sites fits the early date."],"evidence_against":["Exodus 1:11 names Rameses as a store city, a name associated with the 13th-century pharaohs.","Many read the 480 years as a schematic number (12 generations of 40 years)."],"reviewed_at":"2026-09-30","history":[{"date":"2026-09-30","text":"First published."}]}'::jsonb, null, null) on conflict (id) do nothing;
