insert into public.posts (id, type, slug, title, dek, topic_id, author_id, status, featured, published_at, reading_minutes, hero, body, footnotes, corrections, video, claim, dispatch, related_slug) values ('5e36123d-4133-5268-2da1-af6d20449e90', 'claim', 'nicaea-chose-the-books-of-the-bible', 'The Council of Nicaea decided which books belong in the Bible.', 'A popular claim, checked against the council’s own records.', (select id from public.topics where slug = 'church-history'), (select id from public.authors where slug = 'editor'), 'published', false, '2026-09-28T12:00:00Z', null, null, '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, null, '{"statement":"The Council of Nicaea decided which books belong in the Bible.","origin":"Repeated in popular books, films and social media posts.","rating":"not_supported","confidence":"high","summary":"No surviving record of the council — its creed, its canons, or eyewitness accounts — discusses the biblical canon. The council addressed the Arian controversy, the date of Easter and church order.","evidence_for":["None from the council’s records or from contemporary accounts."],"evidence_against":["The creed and the twenty canons say nothing about which books are Scripture.","Eusebius, who attended, describes the proceedings without mentioning the canon.","Lists of New Testament books both before and after 325 show a gradual process."],"reviewed_at":"2026-09-28","history":[{"date":"2026-09-28","text":"First published."}]}'::jsonb, null, null) on conflict (id) do nothing;
